UPDATE lessons SET title='Year 7, Week 7, Lesson 3: Simile, metaphor and personification', data=json_patch(data,'{"child_mission":"Simile uses like/as; metaphor states one thing is another; personification gives human qualities to non-human things. Avoid mixed metaphors that clash (''the fire of ice drowned us'') unless deliberate for confusion. Explain effect each time.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nRepair or replace a mixed metaphor and explain: ''His courage was a rock that soared on wings of steel.''\n\nFEEDBACK\nStrong answer: Chooses one coherent image family and states clearer effect.\n\nCHECK\nStacking three figurative devices in one line until meaning collapses.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nWrite nine lines using each device three times total across the set; annotate effects; avoid mixed clashes.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Simile uses like/as; metaphor states one thing is another; personification gives human qualities to non-human things. Avoid mixed metaphors that clash (''the fire of ice drowned us'') unless deliberate for confusion. Explain effect each time.","lesson_number":3,"lesson_role":"Language and vocabulary","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN4-URA-01"],"parent_notes":"Parent: Marking guidance for the independent task